import { memo, useMemo, useCallback, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Play, Star, Bookmark, BookmarkCheck } from 'lucide-react';
import { img } from '../lib/tmdb';
import { useSettings } from '../contexts/SettingsContext';
import { useToast } from '../contexts/ToastContext';

// Watchlist cache to avoid repeated localStorage reads
const watchlistCache = new Map<number, boolean>();
let watchlistLoadTime = 0;

function getWatchlistStatus(id: number): boolean {
  // Invalidate cache every 5 seconds to stay in sync with other components
  if (Date.now() - watchlistLoadTime > 5000) {
    watchlistCache.clear();
    watchlistLoadTime = Date.now();
  }
  if (watchlistCache.has(id)) return watchlistCache.get(id)!;
  try {
    const saved = localStorage.getItem(`watchlist-item-${id}`);
    const status = saved !== null;
    watchlistCache.set(id, status);
    return status;
  } catch {
    return false;
  }
}

function getAndSetWatchlistStatus(id: number): boolean {
  return getWatchlistStatus(id);
}

interface MediaCardProps {
  item: {
    id: number;
    title: string;
    poster_path: string | null;
    backdrop_path: string | null;
    overview: string;
    vote_average: number;
    media_type?: 'movie' | 'tv';
    poster?: string;
  };
  mediaType?: 'movie' | 'tv';
  index?: number;
  viewMode?: 'grid' | 'list';
}

// Pre-computed poster URL to avoid repeated string concatenation
const getPosterUrl = (item: MediaCardProps['item']): string | null => {
  if (item.poster) return item.poster;
  return item.poster_path ? img(item.poster_path, 'w342') : null;
};

function MediaCardInner({ item, mediaType, index = 0, viewMode = 'grid' }: MediaCardProps) {
  const navigate = useNavigate();
  const { settings } = useSettings();
  const { addToast } = useToast();
  const type = mediaType || (item.media_type as 'movie' | 'tv') || 'movie';
  const title = item.title || item.name || 'Untitled';
  const poster = getPosterUrl(item);

  // Memoized watchlist status with cache
  const [isInWatchlist, setIsInWatchlist] = useMemo(() => {
    const status = getAndSetWatchlistStatus(item.id);
    // Return state pair with setter
    return [status, status] as [boolean, React.Dispatch<React.SetStateAction<boolean>>];
  }, [item.id]);

  const [watchlistStatus, setWatchlistStatus] = useMemo(() => {
    let status = getWatchlistStatus(item.id);
    const getter = () => status;
    const setter = (updater: React.SetStateAction<boolean>) => {
      status = typeof updater === 'function' ? updater(status) : updater;
    };
    return [getter(), setter] as [boolean, React.Dispatch<React.SetStateAction<boolean>>];
  }, [item.id]);

  // Use effect to sync watchlist status
  const [isInWatchlistState, setIsInWatchlistState] = useMemo(() => {
    const s = getWatchlistStatus(item.id);
    return [s, s] as [boolean, boolean];
  }, [item.id]);

  const toggleWatchlist = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      const ids = localStorage.getItem('watchlist-ids');
      const idList: number[] = ids ? JSON.parse(ids) : [];
      const currentlyInList = getWatchlistStatus(item.id);

      if (currentlyInList) {
        const newList = idList.filter((i: number) => i !== item.id);
        localStorage.setItem('watchlist-ids', JSON.stringify(newList));
        localStorage.removeItem(`watchlist-item-${item.id}`);
        watchlistCache.delete(item.id);
        setWatchlistStatus(false);
        addToast('Removed from watchlist', 'info');
      } else {
        if (!idList.includes(item.id)) {
          const newList = [...idList, item.id];
          localStorage.setItem('watchlist-ids', JSON.stringify(newList));
          localStorage.setItem(`watchlist-item-${item.id}`, JSON.stringify({
            id: item.id,
            title,
            poster_path: item.poster_path,
            media_type: type,
          }));
          watchlistCache.set(item.id, true);
          setWatchlistStatus(true);
          addToast('Added to watchlist', 'success');
        }
      }
    } catch (error) {
      console.error('Failed to toggle watchlist:', error);
    }
  }, [item.id, title, item.poster_path, type, addToast, setWatchlistStatus]);

  const handleNavigate = useCallback(() => {
    navigate(`/${type}/${item.id}`);
  }, [navigate, type, item.id]);

  // Grid view
  if (viewMode === 'list') {
    return (
      <div
        onClick={handleNavigate}
        className="flex gap-3 p-2.5 bg-white/5 hover:bg-white/10 rounded-lg transition-all cursor-pointer group/list border border-transparent hover:border-white/10"
        style={{ contain: 'layout style', willChange: 'background-color' }}
        role="button"
        tabIndex={0}
        onKeyDown={handleNavigate}
      >
        <div className="relative w-16 h-24 flex-shrink-0 overflow-hidden rounded-md">
          {poster ? (
            <img
              src={poster}
              alt={title}
              className="w-full h-full object-cover"
              loading="lazy"
              style={{ contain: 'strict' }}
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-emerald-500/20 to-emerald-600/20 flex items-center justify-center">
              <span className="text-white/30 text-xl font-bold">{title[0]}</span>
            </div>
          )}
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="text-white text-sm font-semibold truncate group-hover/list:text-emerald-400 transition-colors">
            {title}
          </h3>
          <div className="flex items-center gap-2 mt-1">
            <span className="flex items-center gap-1 text-amber-400 text-xs">
              <Star size={10} className="fill-amber-400" />
              {item.vote_average?.toFixed(1) || 'N/A'}
            </span>
            <span className="text-white/30 text-xs">•</span>
            <span className="text-white/40 text-xs capitalize">{type}</span>
          </div>
        </div>
        <div className="flex flex-col gap-1.5">
          <button
            onClick={toggleWatchlist}
            className="p-1.5 text-white/40 hover:text-emerald-400 transition-all"
            aria-label={isInWatchlistState ? 'Remove from watchlist' : 'Add to watchlist'}
          >
            {isInWatchlistState ? <BookmarkCheck size={14} /> : <Bookmark size={14} />}
          </button>
        </div>
      </div>
    );
  }

  // Grid view
  return (
    <div
      onClick={handleNavigate}
      className="group relative rounded-xl overflow-hidden cursor-pointer transition-all duration-300 hover:scale-105 hover:z-10 hover:shadow-2xl shadow-black/50 bg-white/5 hover:bg-white/10 border border-transparent hover:border-white/20"
      style={{ contain: 'layout style', willChange: 'transform' }}
      role="button"
      tabIndex={0}
      onKeyDown={handleNavigate}
    >
      <div className="relative aspect-[2/3] overflow-hidden">
        {poster ? (
          <img
            src={poster}
            alt={title}
            className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
            loading="lazy"
            style={{
              animationDelay: `${index * 50}ms`,
              contain: 'strict',
              transform: 'translateZ(0)',
            }}
          />
        ) : (
          <div className="w-full h-full bg-gradient-to-br from-emerald-500/20 to-emerald-600/20 flex items-center justify-center">
            <span className="text-white/30 text-4xl font-bold">{title[0]}</span>
          </div>
        )}
        <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent opacity-0 group-hover:opacity-100 transition-all duration-300 flex flex-col justify-end p-3">
          <div className="flex items-center gap-2 mb-2">
            <button
              onClick={(e) => {
                e.stopPropagation();
                navigate(`/${type}/${item.id}`);
              }}
              className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-500 hover:bg-emerald-400 text-white rounded-md transition-all text-xs font-bold shadow-lg"
            >
              <Play size={12} fill="white" />
              Watch
            </button>
          </div>
          <h3 className="text-white text-sm font-semibold leading-tight line-clamp-2 mb-1 group-hover:text-emerald-400 transition-colors">
            {title}
          </h3>
          <div className="flex items-center gap-1.5">
            <span className="flex items-center gap-1 text-amber-400 text-xs">
              <Star size={10} className="fill-amber-400" />
              {item.vote_average?.toFixed(1) || 'N/A'}
            </span>
          </div>
        </div>
        <button
          onClick={toggleWatchlist}
          className="absolute top-2 right-2 p-1.5 bg-black/60 hover:bg-emerald-500 text-white/60 hover:text-white rounded-md transition-all opacity-0 group-hover:opacity-100"
          aria-label={isInWatchlistState ? 'Remove from watchlist' : 'Add to watchlist'}
        >
            {isInWatchlistState ? <BookmarkCheck size={14} /> : <Bookmark size={14} />}
        </button>
        {settings.showQuality && (
          <div className="absolute top-2 left-2 px-1.5 py-0.5 bg-black/70 backdrop-blur-sm rounded text-[9px] font-bold text-white uppercase">
            HD
          </div>
        )}
      </div>
      <div className="p-2.5">
        <h3 className="text-white text-xs sm:text-sm font-medium truncate group-hover:text-emerald-400 transition-colors">
          {title}
        </h3>
        <div className="flex items-center justify-between mt-0.5">
          <span className="flex items-center gap-1 text-white/30 text-[10px]">
            <Star size={9} className="text-amber-400/70 fill-amber-400/70" />
            {item.vote_average?.toFixed(1) || 'N/A'}
          </span>
          <span className="text-white/20 text-[10px] capitalize">{type}</span>
        </div>
      </div>
    </div>
  );
}

export default memo(MediaCardInner);